contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 dummy) public {
        require(dummy == dummy);

        c.XBornID(); if (__ESBMC_reverted()) return;

        assert(c.balanceOf(address(this)) == 200000000e18);
    }
}

